import math
import sys

def d2(ax, ay, bx, by):
    return (bx - ax) ** 2 + (by - ay) ** 2

def cross_simple(x, y, r, tx, ty, tr):
    d2Val = d2(x, y, tx, ty)
    if d2Val < (r - tr) ** 2 or d2Val > (r + tr) ** 2:
        return []
    base = math.atan2(ty - y, tx - x)
    wing = math.acos((d2Val + r ** 2 - tr ** 2) / (2.0 * math.sqrt(d2Val) * r))
    return [base - wing, base + wing]

def main():
    input_data = sys.stdin.read().strip().split('\n')
    n = int(input_data[0].strip())
    circles = []
    for i in range(1, n + 1):
        parts = input_data[i].split()
        circles.append([int(parts[0]), int(parts[1]), int(parts[2])])
    points = []
    for i in range(n):
        for j in range(i + 1, n):
            angles = cross_simple(circles[i][0], circles[i][1], circles[i][2],
                                  circles[j][0], circles[j][1], circles[j][2])
            for angle in angles:
                points.append([
                    circles[i][0] + circles[i][2] * math.cos(angle),
                    circles[i][1] + circles[i][2] * math.sin(angle)
                ])
    pts_array = points
    length = len(pts_array)
    discard = [False] * length
    for i in range(length):
        for j in range(i + 1, length):
            if d2(pts_array[i][0], pts_array[i][1], pts_array[j][0], pts_array[j][1]) < 1e-12:
                discard[j] = True
    unique_points = [pts_array[i] for i in range(length) if not discard[i]]
    total_points = len(unique_points)
    total_edges = 0
    components = 1
    for i in range(n):
        edge_count = 0
        for p in unique_points:
            if abs(d2(p[0], p[1], circles[i][0], circles[i][1]) - circles[i][2] ** 2) < 1e-12:
                edge_count += 1
        if edge_count == 0:
            components += 1
        total_edges += edge_count
    if components > n:
        components = n
    print(total_edges - total_points + components + 1)

if __name__ == "__main__":
    main()

